"""Conway's Game of Life, computed generation by generation on the GPU.

Usage: uv run main.py <input-file>

The input file holds "<width> <height> <generations>" followed by height rows
of width digits (0 or 1). The final grid is printed as rows of digits, then
"ALIVE <count>".
"""

import sys
from array import array

import wgpu

WORKGROUP = 16

# One thread per cell. Each thread counts its eight neighbours in the source
# buffer (cells outside the grid are dead) and writes the next state to the
# destination buffer, so no thread ever sees a cell decided in this generation.
SHADER = """
struct Params {
    width: u32,
    height: u32,
}

@group(0) @binding(0) var<storage, read> src: array<u32>;
@group(0) @binding(1) var<storage, read_write> dst: array<u32>;
@group(0) @binding(2) var<uniform> params: Params;

@compute @workgroup_size(%d, %d)
fn step(@builtin(global_invocation_id) id: vec3<u32>) {
    let x = id.x;
    let y = id.y;
    if (x >= params.width || y >= params.height) {
        return;
    }

    var neighbours: u32 = 0u;
    for (var dy: i32 = -1; dy <= 1; dy++) {
        for (var dx: i32 = -1; dx <= 1; dx++) {
            if (dx == 0 && dy == 0) {
                continue;
            }
            let nx = i32(x) + dx;
            let ny = i32(y) + dy;
            if (nx >= 0 && ny >= 0 && nx < i32(params.width) && ny < i32(params.height)) {
                neighbours += src[u32(ny) * params.width + u32(nx)];
            }
        }
    }

    let alive = src[y * params.width + x] != 0u;
    let next = (alive && (neighbours == 2u || neighbours == 3u)) || (!alive && neighbours == 3u);
    dst[y * params.width + x] = select(0u, 1u, next);
}
""" % (WORKGROUP, WORKGROUP)


def parse(text):
    """Return (width, height, generations, cells) from the input text.

    cells is a flat row-major list of 0/1 ints. Digits are collected from
    everything after the three header numbers, so single-space separation
    and any other whitespace layout both parse.
    """
    tokens = text.split()
    if len(tokens) < 3:
        raise ValueError("missing header")
    width, height, generations = (int(t) for t in tokens[:3])
    if not (1 <= width <= 512 and 1 <= height <= 512 and 0 <= generations <= 1000):
        raise ValueError("header out of range")

    digits = "".join(tokens[3:])
    if len(digits) != width * height or set(digits) - {"0", "1"}:
        raise ValueError("grid does not match header")
    return width, height, generations, [int(c) for c in digits]


def run(width, height, generations, cells):
    """Advance the grid on the GPU and return the final cells as a flat list."""
    instance_adapter = wgpu.gpu.request_adapter_sync(power_preference="high-performance")
    device = instance_adapter.request_device_sync()

    size = width * height * 4
    buffers = [
        device.create_buffer(
            size=size,
            usage=wgpu.BufferUsage.STORAGE | wgpu.BufferUsage.COPY_SRC | wgpu.BufferUsage.COPY_DST,
        )
        for _ in range(2)
    ]
    params = device.create_buffer(
        size=16,
        usage=wgpu.BufferUsage.UNIFORM | wgpu.BufferUsage.COPY_DST,
    )

    initial = array("I", cells)
    assert initial.itemsize == 4
    device.queue.write_buffer(buffers[0], 0, initial)
    device.queue.write_buffer(params, 0, array("I", [width, height, 0, 0]))

    if generations:
        module = device.create_shader_module(code=SHADER)
        pipeline = device.create_compute_pipeline(
            layout="auto",
            compute={"module": module, "entry_point": "step"},
        )
        layout = pipeline.get_bind_group_layout(0)

        # bind_groups[i] reads buffers[i] and writes buffers[1 - i].
        bind_groups = [
            device.create_bind_group(
                layout=layout,
                entries=[
                    {"binding": 0, "resource": {"buffer": buffers[i], "offset": 0, "size": size}},
                    {"binding": 1, "resource": {"buffer": buffers[1 - i], "offset": 0, "size": size}},
                    {"binding": 2, "resource": {"buffer": params, "offset": 0, "size": 16}},
                ],
            )
            for i in range(2)
        ]

        groups_x = (width + WORKGROUP - 1) // WORKGROUP
        groups_y = (height + WORKGROUP - 1) // WORKGROUP
        encoder = device.create_command_encoder()
        compute = encoder.begin_compute_pass()
        compute.set_pipeline(pipeline)
        for generation in range(generations):
            compute.set_bind_group(0, bind_groups[generation % 2])
            compute.dispatch_workgroups(groups_x, groups_y)
        compute.end()
        device.queue.submit([encoder.finish()])

    final = buffers[generations % 2]
    result = array("I")
    result.frombytes(bytes(device.queue.read_buffer(final)))
    return list(result)


def render(width, height, cells):
    """Format the grid in the input's row format, followed by the ALIVE line."""
    lines = []
    for row in range(height):
        lines.append(" ".join(str(c) for c in cells[row * width:(row + 1) * width]))
    lines.append(f"ALIVE {sum(cells)}")
    return "\n".join(lines) + "\n"


def main(argv):
    if len(argv) != 2:
        print("usage: main.py <input-file>", file=sys.stderr)
        return 2
    with open(argv[1], encoding="utf-8") as f:
        width, height, generations, cells = parse(f.read())
    final = run(width, height, generations, cells)
    sys.stdout.write(render(width, height, final))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

